import React, { useEffect, useState } from 'react';
import PropTypes from 'prop-types';

import { CRow, CCol, CWidgetStatsA } from '@coreui/react';
import { getStyle } from '@coreui/utils';
import { CChartLine } from '@coreui/react-chartjs';
import CIcon from '@coreui/icons-react';
import { cilArrowTop, cilArrowBottom, cilPeople, cilCart, cibBlogger } from '@coreui/icons';

const months = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const WidgetsDropdown = ({ users, orders, products, brands, categories, blogs }) => {
  const [stats, setStats] = useState({});

  const calculateStats = (data) => {
    const monthlyCounts = Array(12).fill(0);

    data.forEach((item) => {
      const monthIndex = new Date(item.created_at).getMonth();
      monthlyCounts[monthIndex] += 1;
    });

    const currentMonth = new Date().getMonth();
    const lastMonthCount = currentMonth > 0 ? monthlyCounts[currentMonth - 1] : 0;
    const thisMonthCount = monthlyCounts[currentMonth];

    let percentageChange = lastMonthCount === 0
      ? (thisMonthCount > 0 ? 100 : 0)
      : ((thisMonthCount - lastMonthCount) / lastMonthCount) * 100;

    percentageChange = Math.max(-100, Math.min(100, Math.round(percentageChange)));

    return {
      monthlyCounts,
      currentMonthCount: thisMonthCount,
      percentageChange,
    };
  };

  useEffect(() => {
    setStats({
      users: calculateStats(users),
      orders: calculateStats(orders),
      products: calculateStats(products),
      brands: calculateStats(brands),
      categories: calculateStats(categories),
      blogs: calculateStats(blogs),
    });
  }, [users, orders, products, brands, categories, blogs]);

  const widgetsData = [
    { title: 'Users', key: 'users', data: users },
    { title: 'Orders', key: 'orders', data: orders },
    { title: 'Products', key: 'products', data: products },
    { title: 'Brands', key: 'brands', data: brands },
    { title: 'Categories', key: 'categories', data: categories },
    { title: 'Blogs', key: 'blogs', data: blogs },
  ];

  return (
    <CRow className="mb-4" xs={{ gutter: 4 }}>
      {widgetsData.map(({ title, key, icon, data }) => {
        if (!stats[key]) return null;

        const { monthlyCounts, currentMonthCount, percentageChange } = stats[key];
        const isPositive = percentageChange >= 0;
        const formattedPercentage = `${isPositive ? '+' : ''}${percentageChange}%`;

        return (
          <CCol key={key} sm={6} xl={4} xxl={3}>
            <CWidgetStatsA
              color='info'
              value={
                <div className="d-flex justify-content-center align-items-center gap-2">
                  <div className="d-flex justify-content-center align-items-center gap-1">
                    <span>{data.length}</span>
                    <span className="fs-6 fw-normal d-flex align-items-center">
                      [<strong>{formattedPercentage}</strong>
                      <CIcon icon={isPositive ? cilArrowTop : cilArrowBottom} size="sm" className='ms-1' />]
                      <span>[{currentMonthCount}]</span>
                    </span>
                  </div>
                </div>
              }
              title={title}
              chart={
                <CChartLine
                  className="mt-3 mx-3"
                  style={{ height: '70px' }}
                  data={{
                    labels: months,
                    datasets: [
                      {
                        label: title,
                        backgroundColor: 'transparent',
                        borderColor: 'rgba(255,255,255,.55)',
                        pointBackgroundColor: getStyle('--cui-info'),
                        data: monthlyCounts,
                      },
                    ],
                  }}
                  options={{
                    plugins: {
                      legend: { display: false }
                    },
                    maintainAspectRatio: false,
                    scales: {
                      x: {
                        border: { display: false },
                        grid: { display: false, drawBorder: false },
                        ticks: { display: false },
                      },
                      y: {
                        min: 0,
                        display: false,
                        grid: { display: false },
                        ticks: { display: false },
                      },
                    },
                    elements: {
                      line: { borderWidth: 1 },
                      point: { radius: 4, hitRadius: 10, hoverRadius: 4 },
                    },
                  }}
                />
              }
            />
          </CCol>
        );
      })}
    </CRow>
  );
};

WidgetsDropdown.propTypes = {
  users: PropTypes.array.isRequired,
  orders: PropTypes.array.isRequired,
  products: PropTypes.array.isRequired,
  brands: PropTypes.array.isRequired,
  categories: PropTypes.array.isRequired,
  blogs: PropTypes.array.isRequired,
};

export default WidgetsDropdown;
